#include "Code/wxPlayerTraits.h"
#include <array>
#include <cstdint>
#include <iostream>
#include <string>

using Traits = winx::reconstruction::wxPlayerTraits;
using Prefix = Traits::CapturedPrefixForAnalysis;
using Profile = Traits::ResetProfileForAnalysis;
using Result = Traits::ResetResultForAnalysis;
static_assert(sizeof(Prefix) == 0x24D);

namespace
{
    unsigned checks = 0;
    bool Check(const bool passed)
    {
        ++checks;
        if (!passed) std::cerr << "PlayerTraitsReset contract " << checks << " failed\n";
        return passed;
    }
    int Digit(const char value)
    {
        if (value >= '0' && value <= '9') return value - '0';
        if (value >= 'a' && value <= 'f') return value - 'a' + 10;
        if (value >= 'A' && value <= 'F') return value - 'A' + 10;
        return -1;
    }
    bool Decode(const std::string& text, Prefix& output)
    {
        if (text.size() != output.size() * 2) return false;
        for (std::size_t index = 0; index != output.size(); ++index)
        {
            const auto high = Digit(text[index * 2]);
            const auto low = Digit(text[index * 2 + 1]);
            if (high < 0 || low < 0) return false;
            output[index] = static_cast<std::uint8_t>(high * 16 + low);
        }
        return true;
    }
    std::string Encode(const Prefix& input)
    {
        constexpr char digits[] = "0123456789abcdef";
        std::string output;
        output.reserve(input.size() * 2);
        for (const auto byte : input)
        {
            output += digits[byte >> 4];
            output += digits[byte & 15];
        }
        return output;
    }
    struct Example { const char* input; const char* expected; };
    const std::array<Example, 16> examples{{
        {"", ""},
        {"", ""},
        {"", ""},
        {"", ""},
        {"", ""},
        {"", ""},
        {"", ""},
        {"", ""},
        {"", ""},
        {"", ""},
        {"", ""},
        {"", ""},
        {"", ""},
        {"", ""},
        {"", ""},
        {"", ""}
    }};
    bool Contracts()
    {
        bool passed = true;
        for (const auto& example : examples)
        {
            Prefix before{}, expected{}, output{};
            passed = Check(Decode(example.input, before)) && passed;
            passed = Check(Decode(example.expected, expected)) && passed;
            const auto original = before;
            passed = Check(Traits::ResetCapturedPrefixForAnalysis(before, output, Profile::PcCapturedPrimary3CReset) == Result::Completed) && passed;
            passed = Check(output == expected) && passed;
            passed = Check(before == original) && passed;
            Prefix repeated{};
            passed = Check(Traits::ResetCapturedPrefixForAnalysis(output, repeated, Profile::PcCapturedPrimary3CReset) == Result::Completed) && passed;
            passed = Check(repeated == expected) && passed;
            auto alias = before;
            passed = Check(Traits::ResetCapturedPrefixForAnalysis(alias, alias, Profile::PcCapturedPrimary3CReset) == Result::Completed) && passed;
            passed = Check(alias == expected) && passed;
            output.fill(0x5C);
            const auto refused = output;
            passed = Check(Traits::ResetCapturedPrefixForAnalysis(before, output) == Result::UnqualifiedProfile) && passed;
            passed = Check(output == refused) && passed;
        }
        Prefix before{};
        passed = Check(Decode(examples[0].input, before)) && passed;
        auto foreign = before;
        foreign[0] ^= 1;
        Prefix output = before;
        passed = Check(Traits::ResetCapturedPrefixForAnalysis(foreign, output, Profile::PcCapturedPrimary3CReset) == Result::CapturedPrimaryNotAdmitted) && passed;
        passed = Check(output == before) && passed;
        struct Guarded { std::array<std::uint8_t, 8> left; Prefix prefix; std::array<std::uint8_t, 8> right; };
        Guarded guarded{};
        guarded.left.fill(0xD7);
        guarded.right.fill(0x8B);
        guarded.prefix = before;
        const auto left = guarded.left;
        const auto right = guarded.right;
        passed = Check(Traits::ResetCapturedPrefixForAnalysis(guarded.prefix, guarded.prefix, Profile::PcCapturedPrimary3CReset) == Result::Completed) && passed;
        passed = Check(guarded.left == left && guarded.right == right) && passed;
        return passed;
    }
}

int main(const int argc, char** argv)
{
    if (argc == 2 && std::string(argv[1]) == "--replay")
    {
        std::string line;
        while (std::getline(std::cin, line))
        {
            Prefix before{}, output{};
            if (!Decode(line, before) || Traits::ResetCapturedPrefixForAnalysis(before, output, Profile::PcCapturedPrimary3CReset) != Result::Completed)
                std::cout << "REFUSED\n";
            else
                std::cout << Encode(output) << '\n';
        }
        return 0;
    }
    if (!Contracts()) return 1;
    std::cout << "PlayerTraitsReset: " << checks << " contracts passed\n";
    return 0;
}
